('guanciale-fracionado-270g', 'Guanciale fracionado 270g', 'CHARCUTARIA & DEFUMADO', 'unidade', 38, 'https://assets.olaclick.app/companies/products/images/800/7bdde3b7-cf85-4392-b05f-b357e7f15e54.png', '{"id":"guanciale-fracionado-270g","nome":"Guanciale fracionado 270g","categoria":"CHARCUTARIA & DEFUMADO","icone":"restaurant","img":"https://assets.olaclick.app/companies/products/images/800/7bdde3b7-cf85-4392-b05f-b357e7f15e54.png","descricao":"Guanciale é uma iguaria italiana, preparado com as bochechas do porco, de onde deriva seu nome (Guancia di Maiale). Jamais cozida, jamais defumada, aqui fazemos como o processo italiano demanda, apenas curada e maturada em nossas câmaras com processo semelhante ao Prosciutto ou Copa. Diferentemente do bacon que possui a sua gordura em camadas, esta peça possui gordura entremeada, semelhante a uma carne de Wagyu. Sua gordura além de saborosa, derrete na boca quando fatiada fininha.","tipo":"unidade","preco":38}'::jsonb, '{"fotos":[{"url":"https://assets.olaclick.app/companies/products/images/800/7bdde3b7-cf85-4392-b05f-b357e7f15e54.png"}]}'::jsonb, 79, true),
