('melado-de-cana-420g', 'Melado de Cana 420g', 'MOLHOS & ANTEPASTOS', 'unidade', 15, 'https://assets.olaclick.app/companies/products/images/800/3525493e-630e-4837-a746-6dd2ab190434.jpg', '{"id":"melado-de-cana-420g","nome":"Melado de Cana 420g","categoria":"MOLHOS & ANTEPASTOS","icone":"water_drop","img":"https://assets.olaclick.app/companies/products/images/800/3525493e-630e-4837-a746-6dd2ab190434.jpg","descricao":"O Melado de Cana é um produto tradicional e delicioso, produzido a partir da cana-de-açúcar. Com seu sabor doce e intenso, ele é perfeito para ser utilizado como acompanhamento para diversos pratos, como queijo coalho, por exemplo. O contraste do sabor salgado do queijo com o adocicado do melado de cana é simplesmente irresistível.","tipo":"unidade","preco":15}'::jsonb, '{"fotos":[{"url":"https://assets.olaclick.app/companies/products/images/800/3525493e-630e-4837-a746-6dd2ab190434.jpg"}]}'::jsonb, 214, true),
