('figo-ramy-carameli-conhaque-frances', 'Figo Ramy carameli conhaque francês', 'DOCES', 'unidade', 58, 'https://assets.olaclick.app/companies/products/images/800/cc3b12b2-71da-4f7c-ba0c-7c52e1d574a7.jpeg', '{"id":"figo-ramy-carameli-conhaque-frances","nome":"Figo Ramy carameli conhaque francês","categoria":"DOCES","icone":"icecream","img":"https://assets.olaclick.app/companies/products/images/800/cc3b12b2-71da-4f7c-ba0c-7c52e1d574a7.jpeg","descricao":"O Doce de Figo Ramy – 600g O Doce de Figo Ramy, em sua embalagem de 600g, é uma escolha perfeita para os amantes de sabores autênticos e sofisticados. Feito com figos frescos e cuidadosamente selecionados, esse doce passa por um processo de cozimento lento, que preserva a textura suculenta e o sabor intenso da fruta. A doçura natural do figo é complementada por uma calda suave e levemente caramelizada, criando uma sobremesa que agrada aos mais variados paladares.","tipo":"unidade","preco":58}'::jsonb, '{"fotos":[{"url":"https://assets.olaclick.app/companies/products/images/800/cc3b12b2-71da-4f7c-ba0c-7c52e1d574a7.jpeg"}]}'::jsonb, 216, true),
