('ambrosia', 'Ambrosia', 'DOCES', 'unidade', 40, 'https://assets.olaclick.app/companies/products/images/800/98b0666b-89b5-4ed9-99c2-e3d8535a8f48.png', '{"id":"ambrosia","nome":"Ambrosia","categoria":"DOCES","icone":"icecream","img":"https://assets.olaclick.app/companies/products/images/800/98b0666b-89b5-4ed9-99c2-e3d8535a8f48.png","descricao":"A Ambrosia é uma sobremesa tradicional da culinária portuguesa, feita com leite, açúcar, ovos e canela. É uma sobremesa cremosa e suave, com uma textura semelhante ao pudim. A ambrosia é cozida lentamente em banho-maria, permitindo que os ingredientes se misturem e criem um sabor rico e complexo. É uma sobremesa deliciosa e reconfortante, perfeita para ser servida em ocasiões especiais ou para desfrutar em um momento de indulgência","tipo":"unidade","preco":40}'::jsonb, '{"fotos":[{"url":"https://assets.olaclick.app/companies/products/images/800/98b0666b-89b5-4ed9-99c2-e3d8535a8f48.png"}]}'::jsonb, 219, true),
