('goiabada-zelia-300g', 'Goiabada Zelia 300g', 'DOCES', 'unidade', 16, 'https://assets.olaclick.app/companies/products/images/800/7992dc1a-5946-442b-8e5b-4346a5ae3210.jpeg', '{"id":"goiabada-zelia-300g","nome":"Goiabada Zelia 300g","categoria":"DOCES","icone":"icecream","img":"https://assets.olaclick.app/companies/products/images/800/7992dc1a-5946-442b-8e5b-4346a5ae3210.jpeg","descricao":"🍯 Goiabada de Corte Zélia – Sabor da Roça A Goiabada de Corte Zélia é um clássico da doçaria mineira, produzida de forma artesanal com goiabas selecionadas e ingredientes naturais. Sua textura firme e macia ao corte, combinada com um sabor intenso e adocicado na medida certa, remete às receitas tradicionais feitas no tacho. Ideal para ser apreciada pura, como sobremesa, ou para harmonizar com queijos artesanais — formando o famoso e irresistível Romeu e Julieta. Sem aditivos artificiais,","tipo":"unidade","preco":16}'::jsonb, '{"fotos":[{"url":"https://assets.olaclick.app/companies/products/images/800/7992dc1a-5946-442b-8e5b-4346a5ae3210.jpeg"}]}'::jsonb, 221, true),
