-- Importa 261 produtos do CSV para a tabela relacional `produtos`.
-- Idempotente (ON CONFLICT). Autossuficiente: cria as colunas necessárias.

-- 0) Garante as colunas relacionais na tabela produtos (caso não existam)
alter table produtos add column if not exists app_id  text;
drop index if exists idx_produtos_app_id;
create unique index idx_produtos_app_id on produtos (app_id);
alter table produtos add column if not exists dados   jsonb;
alter table produtos add column if not exists cfg     jsonb;
alter table produtos add column if not exists ordem   integer not null default 0;

-- 1) Registra as categorias na config (para aparecerem na loja)
update config_app set dados = jsonb_set(coalesce(dados,'{}'::jsonb),'{categorias}',
  (select jsonb_agg(c) from (select cat as c from jsonb_array_elements_text(coalesce(dados->'categorias','[]'::jsonb)) t(cat) union select unnest(array['CAFÉ GOURMET','NOVIDADES','PROMOÇÃO','TÁBUA DE FRIOS','CONGELADOS','QUEIJO CASCA FLORIDA','DESIDRATADO/GRISSINI /RISOTO','TRUFADO/PATÊS/MANTEIGA','CHARCUTARIA & DEFUMADO','GELEIAS','QUEIJO CANASTRA','QUEIJOS PARA O DIA A DIA','QUEIJO BÚFALA','QUEIJO CABRA','QUEIJO MEIA CURA','PARMESÃO','ZERO LACTOSE','ZERO AÇÚCAR','ZERO AÇÚCAR E ZERO LACTOSE','PÃO DE QUEIJO','MOLHOS & ANTEPASTOS','DOCES','MEL','PIMENTAS','QUEIJO OVELHA','Coalho']::text[])) u)
) where id='principal';

-- 2) Insere os produtos
on conflict (app_id) do update set nome=excluded.nome, categoria=excluded.categoria, tipo_preco=excluded.tipo_preco, preco_venda=excluded.preco_venda, foto_url=excluded.foto_url, dados=excluded.dados, cfg=excluded.cfg, ordem=excluded.ordem, ativo=true;
